[patterns/infrastructure/event-driven/PTN-INFRA-EVT-006-infrastructure-event-retention-pattern.md#example-3-terraform-module-for-ebs-snapshot-lifecycle-policy]

#### Example 3: Terraform Module for EBS Snapshot Lifecycle Policy

```hcl
# modules/ebs-snapshot-lifecycle/main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  type        = string
  description = "Environment classification: production, staging, development, sandbox"
  validation {
    condition     = contains(["production", "staging", "development", "sandbox"], var.environment)
    error_message = "Environment must be production, staging, development, or sandbox"
  }
}

variable "application_name" {
  type        = string
  description = "Application name for policy naming and resource tagging"
}

variable "target_tags" {
  type        = map(string)
  description = "Tags identifying EBS volumes to include in lifecycle policy"
  default = {
    "Backup" = "true"
  }
}

variable "cross_region_copy_enabled" {
  type        = bool
  description = "Enable cross-region snapshot copy for disaster recovery"
  default     = false
}

variable "cross_region_target" {
  type        = string
  description = "Target region for cross-region snapshot copies"
  default     = "us-west-2"
}

locals {
  retention_days = {
    production  = 35
    staging     = 14
    development = 7
    sandbox     = 3
  }

  snapshot_schedule = {
    production  = "cron(0 3 * * ? *)"  # Daily at 3:00 AM
    staging     = "cron(0 3 * * ? *)"  # Daily at 3:00 AM
    development = "cron(0 3 * * ? *)"  # Daily at 3:00 AM
    sandbox     = "cron(0 10 * * 0 *)" # Weekly on Sunday at 10:00 AM
  }
}

resource "aws_dlm_lifecycle_policy" "ebs_snapshot_policy" {
  description        = "EBS snapshot lifecycle policy for ${var.application_name} ${var.environment}"
  execution_role_arn = aws_iam_role.dlm_lifecycle_role.arn
  state              = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]

    schedule {
      name = "${var.application_name}-${var.environment}-daily-snapshots"

      create_rule {
        cron_expression = local.snapshot_schedule[var.environment]
      }

      retain_rule {
        count = local.retention_days[var.environment]
      }

      tags_to_add = {
        SnapshotType   = "DLM-Automated"
        Application    = var.application_name
        Environment    = var.environment
        RetentionDays  = local.retention_days[var.environment]
        ManagedBy      = "Terraform"
      }

      copy_tags = true

      dynamic "cross_region_copy_rule" {
        for_each = var.cross_region_copy_enabled && var.environment == "production" ? [1] : []

        content {
          target    = var.cross_region_target
          encrypted = true

          retain_rule {
            interval      = local.retention_days[var.environment]
            interval_unit = "DAYS"
          }

          copy_tags = true
        }
      }
    }

    target_tags = merge(
      var.target_tags,
      {
        Environment = var.environment
      }
    )
  }

  tags = {
    Name           = "${var.application_name}-${var.environment}-dlm-policy"
    Application    = var.application_name
    Environment    = var.environment
    ManagedBy      = "Terraform"
  }
}

resource "aws_iam_role" "dlm_lifecycle_role" {
  name = "${var.application_name}-${var.environment}-dlm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Application = var.application_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_iam_role_policy" "dlm_lifecycle_policy" {
  name = "${var.application_name}-${var.environment}-dlm-policy"
  role = aws_iam_role.dlm_lifecycle_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateSnapshot",
          "ec2:CreateSnapshots",
          "ec2:DeleteSnapshot",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:EnableFastSnapshotRestores",
          "ec2:DescribeFastSnapshotRestores",
          "ec2:DisableFastSnapshotRestores",
          "ec2:CopySnapshot",
          "ec2:ModifySnapshotAttribute",
          "ec2:DescribeSnapshotAttribute"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateTags"
        ]
        Resource = "arn:aws:ec2:*::snapshot/*"
      }
    ]
  })
}

output "policy_id" {
  description = "DLM Lifecycle Policy ID"
  value       = aws_dlm_lifecycle_policy.ebs_snapshot_policy.id
}

output "policy_arn" {
  description = "DLM Lifecycle Policy ARN"
  value       = aws_dlm_lifecycle_policy.ebs_snapshot_policy.arn
}

output "retention_days" {
  description = "Configured retention period in days"
  value       = local.retention_days[var.environment]
}

# Example usage in application Terraform configuration:
# module "ebs_snapshot_lifecycle" {
#   source                   = "../../modules/ebs-snapshot-lifecycle"
#   environment              = "production"
#   application_name         = "claims-processing"
#   cross_region_copy_enabled = true
#   cross_region_target      = "us-west-2"
#
#   target_tags = {
#     Backup      = "true"
#     Application = "claims-processing"
#   }
# }
```

**Explanation**: Terraform module automates EBS snapshot lifecycle management with environment-specific retention: production (35 days, daily snapshots), staging (14 days), development (7 days), sandbox (3 days weekly). Module creates DLM policy targeting EBS volumes with specified tags (e.g., `Backup=true`, `Application=claims-processing`). For production environments, module optionally enables cross-region snapshot copy with identical retention for disaster recovery. Module includes IAM role with least-privilege permissions for DLM service.

**Use Case**: Application teams include this module in their Terraform infrastructure code. By specifying only environment and application name, teams receive automated EBS snapshot management aligned with organizational standards. Eliminates manual snapshot creation/deletion and prevents indefinite snapshot retention. 60% cost reduction for non-production environments through automated 7-14 day retention vs. previous 35-90 day manual retention.
